#include <map>
#include <string>
#include <vector>

class Registry
{
public:
    bool add(const std::string& owner, const std::string& id, int weight)
    {
        const auto dot{ id.find('.') };
        if (dot == std::string::npos || dot == 0 || dot + 1 >= id.size()) return false;
        if (id.substr(0, dot) != owner) return false;
        if (m_entries.count(id)) return false;
        m_entries[id] = Entry{ owner, weight };
        return true;
    }

    int weightOf(const std::string& id) const
    {
        const auto it{ m_entries.find(id) };
        return it == m_entries.end() ? -1 : it->second.weight;
    }

    std::string ownerOf(const std::string& id) const
    {
        const auto it{ m_entries.find(id) };
        return it == m_entries.end() ? "" : it->second.owner;
    }

    int removeOwner(const std::string& owner)
    {
        int removed{ 0 };
        for (auto it{ m_entries.begin() }; it != m_entries.end();)
        {
            if (it->second.owner == owner) { it = m_entries.erase(it); ++removed; }
            else ++it;
        }
        return removed;
    }

    std::vector<std::string> ids() const
    {
        std::vector<std::string> out;
        for (const auto& [id, entry] : m_entries) out.push_back(id);
        return out;
    }

private:
    struct Entry { std::string owner; int weight; };
    std::map<std::string, Entry> m_entries;
};

unitTests:
TEST("add and look up") { Registry r; CHECK(r.add("fog", "fog.ghost_stone", 2)); CHECK_EQ(r.weightOf("fog.ghost_stone"), 2); CHECK_EQ(r.ownerOf("fog.ghost_stone"), std::string("fog")); }
TEST("duplicates refused") { Registry r; CHECK(r.add("fog", "fog.mist", 1)); CHECK(!r.add("fog", "fog.mist", 9)); CHECK_EQ(r.weightOf("fog.mist"), 1); }
TEST("namespacing") { Registry r; CHECK(!r.add("fog", "ghost", 1)); CHECK(!r.add("fog", ".ghost", 1)); CHECK(!r.add("fog", "fog.", 1)); CHECK(!r.add("fog", "rain.drop", 1)); CHECK(r.add("rain", "rain.drop", 1)); }
TEST("remove an owner") {
    Registry r; r.add("fog", "fog.a", 1); r.add("rain", "rain.b", 2); r.add("fog", "fog.c", 3);
    CHECK_EQ(r.removeOwner("fog"), 2); CHECK_EQ(r.ids(), (std::vector<std::string>{ "rain.b" })); CHECK_EQ(r.weightOf("fog.a"), -1); CHECK_EQ(r.removeOwner("fog"), 0);
}
TEST("unknown ids") { Registry r; CHECK_EQ(r.weightOf("x.y"), -1); CHECK_EQ(r.ownerOf("x.y"), std::string("")); }
TEST("sorted ids") { Registry r; r.add("z", "z.z", 1); r.add("a", "a.b", 1); r.add("m", "m.n", 1); CHECK_EQ(r.ids(), (std::vector<std::string>{ "a.b", "m.n", "z.z" })); }

